# SECTION 9: Backtest output is computed by the self-financing accounting engine.
def run_backtest_from_transaction_costs(tc_object:dict,returns:pd.DataFrame)->dict:
    if not tc_object["weights"].index.equals(returns.index) or not tc_object["weights"].columns.equals(returns.columns):
        raise ValueError("backtest returns misaligned")
    gross=tc_object["gross_returns"]
    net=tc_object["net_returns"]
    costs=tc_object["trading_costs"]
    np.testing.assert_allclose(gross-costs,net,atol=1e-10,rtol=1e-10)
    return {"gross_returns":gross,"trading_costs":costs,"net_returns":net,
            "cumulative_net_returns":tc_object["equity_curve_net"]-1,
            "equity_curve_net":tc_object["equity_curve_net"]}

daily_backtests={name:run_backtest_from_transaction_costs(tc,daily_returns)
                 for name,tc in daily_transaction_costs.items()}
four_hour_backtests={name:run_backtest_from_transaction_costs(tc,returns_4h)
                     for name,tc in four_hour_transaction_costs.items()}
